import type { CatalogueField } from './validation';
import type {
  DrapeCharacter,
  FabricBehaviourId,
  HeadingId,
  PatternId,
  SheenLevel,
  SurfaceCharacter,
} from '../knowledge/types';

export type FabricSourceKind = 'supplier' | 'shopify' | 'manual-review' | 'fixture';
export type FactAuthority = 'verified' | 'source-provided' | 'classified' | 'unknown';
export type FabricCareClass = 'easy-care' | 'specialist-cleaning' | 'unknown';
export type FabricPriceBand = 'value' | 'mid' | 'premium' | 'unknown';
export type BlackoutCapability = 'integrated' | 'lining-supported' | 'none' | 'unknown';
export type TechnicalDecisionState =
  'supported' | 'conditional' | 'insufficient-information' | 'incompatible';

export interface FabricSourceReference {
  kind: FabricSourceKind | 'image-classification';
  reference: string;
  field?: string;
  recordKey?: string;
  decisionId?: string;
}

export interface FabricFact<T> {
  value: T;
  authority: FactAuthority;
  source: FabricSourceReference;
  note?: string;
  supportingAssertions?: {
    value: T;
    authority: FactAuthority;
    source: FabricSourceReference;
    note?: string;
  }[];
}

export interface CanonicalFabric {
  visualFingerprintRef?: { digest: string; version: string };
  /** Exact enrichment identity; no raw manufacturer prose. */
  fingerprintRef?: { digest: string; ruleVersion: string; ontologyVersion: string };
  designCharacter?: FabricFact<string[]>;
  /** Exhaustive explicit inventory of unestablished fields; generated by the compiler. */
  unknownFields: CatalogueField[];
  sourceRecords?: { recordKey: string; reference: string; kind: FabricSourceKind }[];
  curtainUse?: FabricFact<
    'ordinary-curtain' | 'specialist-curtain' | 'other-textile' | 'catalogue-fabric'
  >;
  id: string;
  sourceKey: string;
  displayName: string;
  supplierName?: string;
  collectionName?: string;
  active?: FabricFact<boolean>;
  sampleAvailable?: FabricFact<boolean>;
  behaviourClass?: FabricFact<FabricBehaviourId>;
  patternClass?: FabricFact<PatternId>;
  colourFamily?: FabricFact<string>;
  colourArchetypeId?: FabricFact<string>;
  colourTemperature?: FabricFact<'warm' | 'cool' | 'balanced'>;
  colourLightness?: FabricFact<'light' | 'mid-tone' | 'deep'>;
  colourSaturation?: FabricFact<'muted' | 'balanced' | 'saturated'>;
  surface?: FabricFact<SurfaceCharacter>;
  sheen?: FabricFact<SheenLevel>;
  drape?: FabricFact<DrapeCharacter>;
  weightGsm?: FabricFact<number>;
  usableWidthCm?: FabricFact<number>;
  patternRepeatCm?: FabricFact<number>;
  composition?: FabricFact<{ fibre: string; proportion: number }[]>;
  careClass?: FabricFact<FabricCareClass>;
  blackoutCapability?: FabricFact<BlackoutCapability>;
  headingCompatibility?: FabricFact<HeadingId[]>;
  priceBand?: FabricFact<FabricPriceBand>;
}

export type FabricIngestionRecord = CanonicalFabric;

export interface FabricMatchContext {
  lining?: 'blackout' | 'standard' | 'unlined';
  headingId: HeadingId;
  windowScale: 'compact' | 'standard' | 'large' | 'extra-large';
  fullness: 'light' | 'standard' | 'full' | 'luxurious';
}

export interface FabricMatchScore {
  fabricId: string;
  eligible: boolean;
  purchaseReady: boolean;
  technicalDecision: TechnicalDecisionState;
  technicalScore: number;
  needScore: number;
  tasteScore: number;
  overallScore: number;
  matchedEvidenceIds: string[];
  reasons: string[];
  cautions: string[];
  exclusions: string[];
  unknowns: string[];
}

export interface FabricSwatchShortlistItem {
  fabricId: string;
  rank: number;
  overallScore: number;
  technicalDecision: TechnicalDecisionState;
  reasons: string[];
  unknowns: string[];
}
